 for(unsigned k=0;k<8;++k){auto bad=w.coins;auto bs=w.breaks;if(k==0)bad.epoch=72;if(k==1)bad.hud_ready=false;if(k==2)bad.parents.begin()->second.position.x=1;if(k==3)bad.factories.erase(bad.factories.begin());if(k==4)bad.random=nullptr;if(k==5)bad.sounds.clear();if(k==6)bs.factories.clear();if(k==7)bs.parents.clear();CHECK(!scene.prepare(data,coin_data,breaks,71,w.handles,bs,bad,error));CHECK(!scene.valid()&&w.random.state()==rng);}
 CHECK(scene.prepare(data,coin_data,breaks,71,w.handles,w.breaks,w.coins,error));CHECK(scene.factories().size()==data->bindings().size());CHECK(!scene.prepare(data,coin_data,breaks,71,w.handles,w.breaks,w.coins,error));std::map<uint32_t,BreakableActor>actors;
 for(const auto&v:data->bindings()){BreakableActor actor;CHECK(actor.prepare(breaks,v.owner,71,w.breaks,error));CHECK(actor.hit(71,breaks.owner(v.owner)->position,w.breaks,error));actors.emplace(v.owner,std::move(actor));}
 w.coins.frame=1;for(const auto&v:data->bindings())CHECK(actors.at(v.owner).advance_idle(71,coin_data->policy().delta,w.breaks,error));const auto before=w.breaks.requests;std::vector<BreakableRequest>other;size_t bursts=0;for(const auto&r:before)if(r.kind==BreakableRequestKind::Coins)++bursts;else other.push_back(r);CHECK(bursts==49);CHECK(!scene.leave(71,breaks,w.breaks,w.coins,error));CHECK(scene.consume(71,breaks,w.breaks,w.coins,error));CHECK(same(other,w.breaks.requests));CHECK(w.random.state()==rng&&w.session.cash==43&&w.session.storage.data()==storage);
 for(const auto&v:data->bindings()){const auto*f=scene.factory(v.owner);CHECK(f&&f->spawning()&&f->remaining()==breaks.owner(v.owner)->coins&&f->position().x==v.position.x&&f->position().y==v.position.y);}
 // Replay and malformed final events cannot partly change any earlier factory.
 const auto&binding=data->bindings().front();const auto*owner=breaks.owner(binding.owner);auto*f=scene.factory(binding.owner);w.coins.physics_step=1;CHECK(f->advance_physics(71,w.coins,error));w.coins.physics_step=2;CHECK(f->advance_physics(71,w.coins,error));CHECK(f->instances().size()==1);const auto id=f->instances().begin()->first;auto*retained=f->actor(id);const auto state=retained->snapshot();const auto random_after_birth=w.random.state();const auto timer=f->timer();
 w.coins.frame=2;w.breaks.requests={request(*owner,1)};CHECK(!scene.consume(71,breaks,w.breaks,w.coins,error));CHECK(f->remaining()==owner->coins-1&&f->actor(id)==retained&&f->timer()==timer&&w.random.state()==random_after_birth);
 for(unsigned k=0;k<10;++k){auto good=request(*owner,2),bad=good;if(k==0)bad.owner=0;if(k==1)bad.epoch=72;if(k==2)bad.identity=1;if(k==3)bad.value[0]=0;if(k==4)bad.value[0]=std::numeric_limits<double>::quiet_NaN();if(k==5)bad.value[1]=1;if(k==6)bad.kind=BreakableRequestKind(99);if(k==7)bad.frame=3;if(k==8)bad.value[2]=1;if(k==9)bad.value[3]=1;w.breaks.requests={good,bad};CHECK(!scene.consume(71,breaks,w.breaks,w.coins,error));CHECK(w.breaks.requests.size()==2&&f->remaining()==owner->coins-1&&f->actor(id)==retained&&retained->snapshot().position.x==state.position.x&&w.random.state()==random_after_birth&&w.session.cash==43);}
 w.breaks.requests={request(*owner,2)};auto&flags=owner->object_flag?w.breaks.object_flags:w.breaks.story_flags;flags[owner->flag]=false;CHECK(!scene.consume(71,breaks,w.breaks,w.coins,error));flags[owner->flag]=true;auto bad=w.coins;bad.parents.begin()->second.token+=1;CHECK(!scene.consume(71,breaks,w.breaks,bad,error));CHECK(scene.consume(71,breaks,w.breaks,w.coins,error));CHECK(w.breaks.requests.empty()&&f->remaining()==owner->coins&&f->actor(id)==retained&&f->timer()==timer);
 w.coins.requests.push_back({CoinRequestKind::DropAudio,71,id,2});CHECK(!scene.leave(71,breaks,w.breaks,w.coins,error));CHECK(scene.valid()&&f->actor(id)==retained);w.coins.requests.clear();w.coins.owners.insert(999);w.coins.factories.insert(9999);CHECK(scene.leave(71,breaks,w.breaks,w.coins,error));CHECK(!scene.valid()&&scene.factories().empty()&&w.coins.owners==std::set<uint64_t>{999}&&w.coins.factories==std::set<uint64_t>{9999});CHECK(!scene.consume(71,breaks,w.breaks,w.coins,error));
 World fresh(*data,*coin_data,breaks);CoinSceneFactories stale;CHECK(stale.prepare(data,coin_data,breaks,71,fresh.handles,fresh.breaks,fresh.coins,error));CHECK(data->load_file(argv[1],error));CHECK(!stale.consume(71,breaks,fresh.breaks,fresh.coins,error));CHECK(fresh.random.state()==rng&&fresh.session.cash==43);std::cout<<checks<<" Coin scene factory consumer checks passed\n";return 0;
